import React from 'react';

function News({ lang }) {
  return (
    <div>
      <h1>
        {lang === 'ru'
          ? 'Новый сезонный напиток!'
          : 'New seasonal drink!'}
      </h1>

      <p>
        {lang === 'ru'
          ? 'Попробуйте карамельный латте со скидкой 20%.'
          : 'Try caramel latte with a 20% discount.'}
      </p>
    </div>
  );
}

export default News;
